import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Page.css";

function Internships() {
  const [jobs, setJobs] = useState([]);
  const [selectedYear, setSelectedYear] = useState(""); // 1st, 2nd, 3rd, 4th
  const [selectedBranch, setSelectedBranch] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = () => {
    setLoading(true);
    axios.get("http://localhost:5000/api/jobs")
      .then(res => {
        // Only show Internships or Entry Level roles for students
        const data = res.data.filter(j => 
          j.jobType === "Internship" || j.jobType === "Entry Level"
        );
        setJobs(data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Fetch error:", err);
        setLoading(false);
      });
  };

  // Local UI Filtering logic updated for Adzuna Data Structure
  const filteredJobs = jobs.filter(job => {
    const matchesYear = selectedYear === "" || job.eligibleYear?.includes(selectedYear);
    
    // Check if selected branch exists in the job's branch array
    const matchesBranch = selectedBranch === "" || job.branch?.includes(selectedBranch);

    return matchesYear && matchesBranch;
  });

  return (
    <div className="page">
      <header className="page-header">
        <h1>B.Tech Career Portal</h1>
        <p>Verified Opportunities for Engineering Students</p>
      </header>

      {/* Filter Section */}
      <div className="filters-bar">
        <div className="filter-item">
          <label>Eligible Year</label>
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)}>
            <option value="">All Years</option>
            <option value="1st">1st Year</option>
            <option value="2nd">2nd Year</option>
            <option value="3rd">3rd Year</option>
            <option value="4th">4th Year / Graduate</option>
          </select>
        </div>

        <div className="filter-item">
          <label>Branch</label>
          <select value={selectedBranch} onChange={e => setSelectedBranch(e.target.value)}>
            <option value="">All Branches</option>
            <option value="CSE">CSE/IT</option>
            <option value="ECE">ECE</option>
            <option value="EEE">EEE</option>
            <option value="Mechanical">Mechanical</option>
            <option value="Civil">Civil</option>
          </select>
        </div>

        <button className="btn-search" onClick={fetchJobs}>
          Refresh Feed
        </button>
      </div>

      {/* Jobs Grid */}
      {loading ? (
        <div className="loader">Updating job feed...</div>
      ) : (
        <div className="jobs-grid">
          {filteredJobs.length > 0 ? (
            filteredJobs.map(job => (
              <div key={job._id} className="job-card">
                <div className="card-body">
                  <div className="card-top">
                    <span className={`type-badge ${job.jobType === 'Internship' ? 'intern' : 'job'}`}>
                      {job.jobType}
                    </span>
                    <span className="source-tag">{job.source}</span>
                  </div>
                  
                  <h3 className="job-title">{job.jobTitle}</h3>
                  <h4 className="company-name">{job.companyName}</h4>
                  
                 

                  

                  <div className="job-info">
                    <span>📍 {job.location}</span>
                    <span>🎓 {job.eligibleYear?.join(", ")} Year</span>
                  </div>
                </div>

                <div className="card-footer">
                  <span className="scraped-date">
                    Sync: {new Date(job.syncedAt).toLocaleDateString()}
                  </span>
                  <a 
                    href={job.applicationLink} 
                    target="_blank" 
                    rel="noreferrer" 
                    className="apply-link"
                  >
                    Apply Now
                  </a>
                </div>
              </div>
            ))
          ) : (
            <div className="empty-state">No matching opportunities found.</div>
          )}
        </div>
      )}
    </div>
  );
}

export default Internships;
